fields.InputDefinition:
{
  "goal": "In the Component Studio app (Components section), click a component card in the left browser to expand it, then click its 'Run' button. Wait for the center Preview pane to mount and render the live component (React-based). On success a live rendered component appears in the preview area and a viewport-size selector (mobile/tablet/desktop icons) becomes available in the preview toolbar; a running indicator/badge may also appear. Pages and component compilation can take 10-30s in this resource-constrained environment — wait, don't navigate away. Seeing the component render live (or a clear inline error overlay with a Retry/Ask-AI-to-Fix affordance) is success — you do NOT need to interact further.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "Expanding a component card reveals a 'Run' action and clicking it starts the component",
    "The center Preview pane renders the live component AND a viewport selector (mobile/tablet/desktop) appears, OR a clear inline error overlay with Retry/Ask-AI-to-Fix is shown",
    "No error messages, blank screens, or crash pages"
  ]
}
